fn branch_sample_counters(event: *const perf_event) -> bool {
(unsafe { (*event).attr.branch_sample_type }) & 524288 != 0
}

fn branch_sample_call_stack(event: *const perf_event) -> bool {
(unsafe { (*event).attr.branch_sample_type }) & 2048 != 0
}

